async resetFromServerAndResyncWithPeers(){let collaborationResetId=this.lastCollaborationResetId;const record=await this.getCurrentRecord();if(collaborationResetId!==this.lastCollaborationResetId){return;}
const content=record[this.config.collaboration.collaborationChannel.collaborationFieldName];this.serverLastStepId=content&&this.getLastHistoryStepId(content);this.isDocumentStale=false;if(content){this.editable.innerHTML=content;}else{this.editable.replaceChildren(this.dependencies.baseContainer.createBaseContainer());}
stripHistoryIds(this.editable);this.dispatchTo("normalize_handlers",this.editable);this.dependencies.history.reset(content);this.historySyncAtLeastOnce=false;this.resetCollabRequests();collaborationResetId=this.lastCollaborationResetId;this.startCollaborationTime=new Date().getTime();await Promise.all(this.getPtpPeers().map((peer)=>{return this.resetFromPeer(peer.id,collaborationResetId);}));return true;}
